#!/usr/bin/env bash
#
# A wizard — walks a human through a manual procedure step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library — delightful, consistent UX. Identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear — wipe the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" — opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later — it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" — clear the screen, then announce a stage and show progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." — a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." — a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL — open in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser — visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser — visit it manually: $url"
}

# pause "msg" — wait for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" — y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY — current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" — read a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" — like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE — upsert KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE — set a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name — gh not ready; set it later"
}

# set_var NAME VALUE — set a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name — gh not ready; set it later"
}

# finish — clear, then a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES — GitHub remote + first android-native CI green (P4-M9/M10).
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=6
ROOT="$(cd "$(dirname "$0")/.." && pwd)"
ENV_FILE="${ENV_FILE:-$ROOT/.env}"

banner "FocusVPN — GitHub CI (android-native ABI)"

stage "Install GitHub CLI (gh)"
say "This host currently has no git remote and may lack gh."
step "If gh is missing: https://cli.github.com/ — install for your OS (or apt/brew)."
open_url "https://cli.github.com/"
pause "Press Enter when gh is installed (or already present)."
if command -v gh >/dev/null 2>&1; then
  note "found: $(command -v gh) ($(gh --version | head -1))"
else
  warn "gh still not on PATH — later stages that call gh will be skipped"
  SKIPPED+=("install gh CLI")
fi

stage "Authenticate gh"
say "Log in so we can create a repo and trigger Actions."
step "Run: gh auth login  (GitHub.com → HTTPS → login with browser or token)."
if command -v gh >/dev/null 2>&1; then
  if gh auth status >/dev/null 2>&1; then
    note "already authenticated"
  else
    pause "Press Enter after: gh auth login"
  fi
else
  SKIPPED+=("gh auth login")
fi
pause "Continue when auth looks good."

stage "Create GitHub repository"
say "Create an empty repo (private recommended until first public release)."
open_url "https://github.com/new"
step "Owner + Repository name (e.g. focusvpn). Do NOT initialize with README if you will push an existing local git tree."
ask GITHUB_OWNER "GitHub owner (user or org):"
ask GITHUB_REPO "Repository name:"
write_env GITHUB_OWNER "$GITHUB_OWNER"
write_env GITHUB_REPO "$GITHUB_REPO"
if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
  if confirm "Create $GITHUB_OWNER/$GITHUB_REPO as a private empty repo via gh now?"; then
    if gh repo create "$GITHUB_OWNER/$GITHUB_REPO" --private --source="$ROOT" --remote=origin 2>/dev/null; then
      note "repo created and origin set"
    elif gh repo create "$GITHUB_OWNER/$GITHUB_REPO" --private 2>/dev/null; then
      note "repo created (add remote in next stage if needed)"
    else
      warn "gh repo create failed — create manually in the browser, then continue"
      SKIPPED+=("gh repo create $GITHUB_OWNER/$GITHUB_REPO")
    fi
  fi
else
  SKIPPED+=("create repo $GITHUB_OWNER/$GITHUB_REPO")
fi

stage "Add git remote origin"
say "Point local master at the new GitHub repo."
REMOTE_URL="https://github.com/${GITHUB_OWNER}/${GITHUB_REPO}.git"
write_env GITHUB_REMOTE_URL "$REMOTE_URL"
note "Suggested: git remote add origin $REMOTE_URL"
if git -C "$ROOT" remote get-url origin >/dev/null 2>&1; then
  note "origin already: $(git -C "$ROOT" remote get-url origin)"
  if confirm "Replace origin with $REMOTE_URL?"; then
    git -C "$ROOT" remote set-url origin "$REMOTE_URL"
    note "origin updated"
  fi
else
  if confirm "Run: git remote add origin $REMOTE_URL ?"; then
    git -C "$ROOT" remote add origin "$REMOTE_URL"
    note "origin added"
  else
    SKIPPED+=("git remote add origin")
  fi
fi

stage "Push workflow + trigger android-native"
warn "Only push when YOU have committed what you want on the remote (agent does not commit)."
step "Ensure .github/workflows/android-native.yml is in a commit on the branch you push."
step "Push: git push -u origin HEAD"
step "Then: Actions → android-native → Run workflow (workflow_dispatch), or push a path that touches the workflow."
open_url "https://github.com/${GITHUB_OWNER}/${GITHUB_REPO}/actions"
pause "Press Enter after the android-native workflow has finished green."

stage "Download ABI artifact + restore jniLibs"
say "Artifact name equals the cache key: libwg-go-v2.0.2-com.focusvpn.app-v0.2.19"
step "On the successful run → Artifacts → download the tarball."
step "Or: gh run download <run-id> -n libwg-go-v2.0.2-com.focusvpn.app-v0.2.19 -D /tmp/focusvpn-abi"
ask ABI_TGZ_PATH "Absolute path to the downloaded .tgz (or directory containing it):"
if [[ -d "$ABI_TGZ_PATH" ]]; then
  CAND=$(find "$ABI_TGZ_PATH" -name 'libwg-go-*.tgz' | head -1 || true)
  [[ -n "$CAND" ]] && ABI_TGZ_PATH="$CAND"
fi
if [[ -f "$ABI_TGZ_PATH" ]]; then
  write_env FOCUSVPN_NATIVE_ABI_TGZ "$ABI_TGZ_PATH"
  if confirm "Run make android-native-restore from this tarball now?"; then
    FOCUSVPN_NATIVE_ABI_TGZ="$ABI_TGZ_PATH" make -C "$ROOT" android-native-restore
  fi
else
  warn "path not found — restore later: FOCUSVPN_NATIVE_ABI_TGZ=… make android-native-restore"
  SKIPPED+=("android-native-restore")
fi

note "Local alternative without GitHub: make android-native-docker"
finish
